export const getListControlCreditLedgerUrl = (
  userId: string,
  params?: ListControlCreditLedgerParams,
) => {
  const normalizedParams = new URLSearchParams()

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  })

  const stringifiedParams = normalizedParams.toString()

  return stringifiedParams.length > 0
    ? `/credits/wallets/${encodeURIComponent(String(userId))}/ledger?${stringifiedParams}`
    : `/credits/wallets/${encodeURIComponent(String(userId))}/ledger`
}

